    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LA1LD_0RD1LA_1LC1RD [SWin 2; SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
