Lemma lapi_1RB0LC_0LB1LA_1RD0LC_0RD1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0LC_0LB1LA_1RD0LC_0RD1LA p q0 E) as (HA & HB).
    exists (0 * 0 + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0LC_0LB1LA_1RD0LC_0RD1LA Z0_1RB0LC_0LB1LA_1RD0LC_0RD1LA Z1_1RB0LC_0LB1LA_1RD0LC_0RD1LA 0 6
               run_z_1RB0LC_0LB1LA_1RD0LC_0RD1LA (Kp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0LC_0LB1LA_1RD0LC_0RD1LA p j' q0 E) as (HA & HB).
    exists (2 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0LC_0LB1LA_1RD0LC_0RD1LA P0_1RB0LC_0LB1LA_1RD0LC_0RD1LA P1_1RB0LC_0LB1LA_1RD0LC_0RD1LA 2 8
               run_p_1RB0LC_0LB1LA_1RD0LC_0RD1LA (Kp q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB0LC_0LB1LA_1RD0LC_0RD1LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LC_0LB1LA_1RD0LC_0RD1LA.
