Lemma fireo_1RB0LC_0RC1LD_0RD1LA_1LC1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_0RC1LD_0RD1LA_1LC1RD = Some t ->
