  unfold Cc_1RB0LC_1LA1LA_1RD0LC_0RD1LA, cden, Z0_1RB0LC_1LA1LA_1RD0LC_0RD1LA, Z1_1RB0LC_1LA1LA_1RD0LC_0RD1LA; cbn [c_st c_l c_h c_r].
