  exists (4 * i + 8), (cden (Ip q0 ++ [S1]) [] i AI1_1RB0LC_1LA1RA_0RD1LA_1LC1RD).
  split; [lia|]. split; [| exact (gen_1RB0LC_1LA1RA_0RD1LA_1LC1RD v i q0 E)].
