  exact (srun_sound tm false true chn_1RB0LC_1LA1RA_0RD1LA_1LC1RD AI0_1RB0LC_1LA1RA_0RD1LA_1LC1RD AI1_1RB0LC_1LA1RA_0RD1LA_1LC1RD 4 8
           run_inner_1RB0LC_1LA1RA_0RD1LA_1LC1RD (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
