Lemma geo_1RB0LC_1LA1RA_0RD1LD_0RB1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_1LA1RA_0RD1LD_0RB1LC) = lift (Cc (Pos.succ p)).
