    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LC_1LA1RA_0RD1LD_0RB1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3; SWinL 1]).
