  - exact bootq_1RB0LC_1LA1RA_1RC1LD_0RB1LC.
  - intros p _. apply lap_1RB0LC_1LA1RA_1RC1LD_0RB1LC.
  - intros t Ht p _. apply fire_1RB0LC_1LA1RA_1RC1LD_0RB1LC. exact Ht.
  - exact wit_1RB0LC_1LA1RA_1RC1LD_0RB1LC.
  - apply qcleb_QC_10. reflexivity.
Qed.

Theorem qhtr_1RB0LC_1LA1RA_1RC1LD_0RB1LC : NonHalt tm_1RB0LC_1LA1RA_1RC1LD_0RB1LC /\ QHBoundTr 32779478 tm_1RB0LC_1LA1RA_1RC1LD_0RB1LC /\ QuasiHaltsTr tm_1RB0LC_1LA1RA_1RC1LD_0RB1LC.
